/* From Uiverse.io by alexruix - Tags: switch */
/* The switch - the box around the slider */
.__UIV_SCOPE__ .switch {
  font-size: 17px;
  position: relative;
  display: inline-block;
  width: 3.5em;
  height: 2em;
}

/* Hide default HTML checkbox */
.__UIV_SCOPE__ .switch input {
  opacity: 0;
  width: 0;
  height: 0;
}

/* The slider */
.__UIV_SCOPE__ .slider {
  position: absolute;
  cursor: pointer;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: #B0B0B0;
  border: 1px solid #B0B0B0;
  transition: .4s;
  border-radius: 32px;
  outline: none;
}

.__UIV_SCOPE__ .slider:before {
  position: absolute;
  content: "";
  height: 2rem;
  width: 2rem;
  border-radius: 50%;
  outline: 2px solid #B0B0B0;
  left: -1px;
  bottom: -1px;
  background-color: #fff;
  transition: transform .25s ease-in-out 0s;
}

.__UIV_SCOPE__ .slider-icon {
  opacity: 0;
  height: 12px;
  width: 12px;
  stroke-width: 8;
  position: absolute;
  z-index: 999;
  stroke: #222222;
  right: 60%;
  top: 30%;
  transition: right ease-in-out .3s, opacity ease-in-out .15s;
}

.__UIV_SCOPE__ input:checked + .slider {
  background-color: #222222;
}

.__UIV_SCOPE__ input:checked + .slider .slider-icon {
  opacity: 1;
  right: 20%;
}

.__UIV_SCOPE__ input:checked + .slider:before {
  transform: translateX(1.5em);
  outline-color: #181818;
}
